  function detectLanguage(languages) {
    const list = languages && languages.length ? languages : (navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || 'en']);
    for (const value of list) {
      const language = String(value || '').toLowerCase();
      if (/^zh-(tw|hk|mo)/.test(language)) return 'zh-TW';
      if (/^zh-(cn|sg)/.test(language) || language === 'zh') return 'zh-CN';
      const base = language.split('-')[0];
      if (I18N[base]) return base;
    }
    return 'en';
  }

  let currentLanguage = detectLanguage();
  let translations = Object.assign({}, en, I18N[currentLanguage] || {});

  function t(key) { return translations[key] || en[key] || key; }

  function applyTranslations(language) {
    currentLanguage = language || detectLanguage();
    translations = Object.assign({}, en, I18N[currentLanguage] || {});
    document.documentElement.lang = currentLanguage;
    document.documentElement.dir = currentLanguage === 'ar' ? 'rtl' : 'ltr';
    document.querySelectorAll('[data-i18n]').forEach((node) => { node.textContent = t(node.dataset.i18n); });
    document.querySelectorAll('[data-i18n-placeholder]').forEach((node) => { node.placeholder = t(node.dataset.i18nPlaceholder); });
    document.querySelectorAll('[data-i18n-aria-label]').forEach((node) => { node.setAttribute('aria-label', t(node.dataset.i18nAriaLabel)); });
    document.title = t('campaignBar');
    return currentLanguage;
  }

  window.CampaignI18n = { I18N, detectLanguage, applyTranslations, t, get language() { return currentLanguage; } };
